const state={category:'All',brand:'All',search:'',sort:'featured',cart:{},wishlist:new Set()};
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const productImage=p=>embeddedProductImages[p.image] || '';
const grid=$('#productGrid');
function renderProducts(){let list=products.filter(p=>(state.category==='All'||state.category==='Offers'||p.category===state.category)&&(state.brand==='All'||p.brand.toLowerCase()===state.brand.toLowerCase())&&(`${p.name} ${p.brand} ${p.category} ${p.subtitle}`.toLowerCase().includes(state.search.toLowerCase())));if(state.category==='Offers')list=list.filter(p=>discount(p)>=15);if(state.sort==='price-low')list.sort((a,b)=>a.price-b.price);if(state.sort==='price-high')list.sort((a,b)=>b.price-a.price);if(state.sort==='rating')list.sort((a,b)=>b.rating-a.rating);grid.innerHTML=list.map(p=>`<article class="product-card"><div class="product-visual ${p.visual}"><span class="product-badge ${p.badgeType}">${p.badge}</span><button class="wishlist-btn ${state.wishlist.has(p.id)?'active':''}" data-wish="${p.id}" aria-label="${state.wishlist.has(p.id)?'Remove from':'Add to'} wishlist">${state.wishlist.has(p.id)?'♥':'♡'}</button><img src="${productImage(p)}" alt="${p.brand} ${p.name}" loading="lazy"></div><div class="product-info"><div class="product-brand">${p.category} · ${p.brand}</div><h3 class="product-title">${p.brand} ${p.name}</h3><div class="product-subtitle">${p.subtitle}</div><div class="rating"><span class="stars">★★★★★</span><span class="rating-number">${p.rating} (${p.reviews.toLocaleString('en-IN')})</span></div><div class="price-row"><span class="price">${money(p.price)}</span><span class="old-price">${money(p.old)}</span><span class="discount">${discount(p)}% OFF</span></div><div class="specs">${p.specs.map((s,i)=>`<span>${['▣','▤','◉'][i%3]} ${s}</span>`).join('')}</div><button class="add-cart" data-add="${p.id}">🛒 &nbsp; Add to Cart</button></div></article>`).join('');$('#emptyState').hidden=!!list.length;grid.hidden=!list.length;updateCounts();}
function discount(p){return Math.round((1-p.price/p.old)*100)}
function updateCounts(){const count=Object.values(state.cart).reduce((a,b)=>a+b,0);$('#cartCount').textContent=count;$('#drawerCount').textContent=`(${count})`;$('#wishCount').textContent=state.wishlist.size;}
function setCategory(cat){state.category=cat;state.brand='All';$$('[data-category]').forEach(b=>b.classList.toggle('selected',b.dataset.category===cat));$$('#filterTabs button').forEach(b=>b.classList.toggle('active',b.dataset.category===cat));renderProducts();if(cat!=='All')document.querySelector('#featured').scrollIntoView({behavior:'smooth',block:'start'});}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
function addToCart(id){state.cart[id]=(state.cart[id]||0)+1;updateCounts();renderCart();toast(`${products.find(p=>p.id===id).name} added to cart`)}
function renderCart(){const entries=Object.entries(state.cart);$('#cartItems').innerHTML=entries.length?entries.map(([id,qty])=>{const p=products.find(x=>x.id===Number(id));return `<div class="cart-item"><img src="${productImage(p)}" alt=""><div><h4>${p.brand} ${p.name}</h4><small>${p.subtitle}</small><div class="quantity-control"><button data-qty="${id}" data-delta="-1" aria-label="Decrease quantity">−</button><span>${qty}</span><button data-qty="${id}" data-delta="1" aria-label="Increase quantity">+</button><button class="remove-item" data-remove="${id}">Remove</button></div></div><div class="cart-item-price">${money(p.price*qty)}</div></div>`}).join(''):'<div class="cart-empty"><span>🛒</span><b>Your cart is waiting for something good.</b><p>Add a few favourites to get started.</p></div>';const total=entries.reduce((sum,[id,qty])=>sum+products.find(p=>p.id===Number(id)).price*qty,0);$('#cartSubtotal').textContent=money(total);$('#demoTotal').textContent=money(total);$('#checkoutBtn').disabled=!entries.length;$('#checkoutBtn').style.opacity=entries.length?'1':'.5';updateCounts()}
function openCart(){$('#overlay').classList.add('show');$('#cartDrawer').classList.add('open');document.body.style.overflow='hidden'}function closeCart(){$('#overlay').classList.remove('show');$('#cartDrawer').classList.remove('open');document.body.style.overflow=''}
function openCheckout(){if(!Object.keys(state.cart).length){toast('Your cart is empty');return}$('#checkoutModal').classList.add('open');$('#overlay').classList.add('show');$('#cartDrawer').classList.remove('open')}
function closeCheckout(){$('#checkoutModal').classList.remove('open');$('#overlay').classList.remove('show');document.body.style.overflow=''}
$('#searchForm').addEventListener('submit',e=>{e.preventDefault();state.search=$('#searchInput').value.trim();renderProducts();$('#featured').scrollIntoView({behavior:'smooth'})});$('#searchInput').addEventListener('input',e=>{state.search=e.target.value.trim();renderProducts()});
$$('[data-category]').forEach(btn=>btn.addEventListener('click',()=>setCategory(btn.dataset.category)));
$$('[data-brand]').forEach(btn=>btn.addEventListener('click',()=>{state.brand=btn.dataset.brand;state.category='All';$$('#filterTabs button').forEach(b=>b.classList.toggle('active',b.dataset.category==='All'));renderProducts();$('#featured').scrollIntoView({behavior:'smooth'})}));
$('#filterTabs').addEventListener('click',e=>{const b=e.target.closest('button[data-category]');if(b)setCategory(b.dataset.category)});$('#sortSelect').addEventListener('change',e=>{state.sort=e.target.value;renderProducts()});grid.addEventListener('click',e=>{const add=e.target.closest('[data-add]');const wish=e.target.closest('[data-wish]');if(add)addToCart(Number(add.dataset.add));if(wish){const id=Number(wish.dataset.wish);state.wishlist.has(id)?state.wishlist.delete(id):state.wishlist.add(id);renderProducts();toast(state.wishlist.has(id)?'Added to wishlist':'Removed from wishlist')}});
$('#cartTop').addEventListener('click',()=>{renderCart();openCart()});$('#closeCart').addEventListener('click',closeCart);$('#overlay').addEventListener('click',()=>{closeCart();closeCheckout()});$('#cartItems').addEventListener('click',e=>{const q=e.target.closest('[data-qty]');const r=e.target.closest('[data-remove]');if(q){const id=Number(q.dataset.qty);state.cart[id]=(state.cart[id]||0)+Number(q.dataset.delta);if(state.cart[id]<=0)delete state.cart[id];renderCart()}if(r){delete state.cart[Number(r.dataset.remove)];renderCart()}});$('#checkoutBtn').addEventListener('click',openCheckout);$('#closeCheckout').addEventListener('click',closeCheckout);$('#placeDemoOrder').addEventListener('click',()=>{state.cart={};renderCart();closeCheckout();closeCart();toast('Demo order placed successfully — no payment taken')});
$('#wishlistTop').addEventListener('click',()=>{state.search='';$('#searchInput').value='';state.category='All';state.brand='All';const ids=[...state.wishlist];if(!ids.length){toast('Your wishlist is empty');return}grid.innerHTML=products.filter(p=>ids.includes(p.id)).map(p=>`<article class="product-card"><div class="product-visual ${p.visual}"><span class="product-badge">Wishlist</span><button class="wishlist-btn active" data-wish="${p.id}">♥</button><img src="${productImage(p)}" alt="${p.name}"></div><div class="product-info"><div class="product-brand">${p.category} · ${p.brand}</div><h3 class="product-title">${p.brand} ${p.name}</h3><div class="product-subtitle">${p.subtitle}</div><div class="price-row"><span class="price">${money(p.price)}</span></div><button class="add-cart" data-add="${p.id}">🛒 &nbsp; Add to Cart</button></div></article>`).join('');$('#emptyState').hidden=true;grid.hidden=false;$('#featured').scrollIntoView({behavior:'smooth'});});
$('#clearFilters').addEventListener('click',()=>{state.category='All';state.brand='All';state.search='';$('#searchInput').value='';renderProducts()});$('#viewAll').addEventListener('click',()=>setCategory('All'));$('#accountBtn').addEventListener('click',()=>toast('Account sign-in is a demo feature'));
$('#newsletterForm').addEventListener('submit',e=>{e.preventDefault();const email=e.currentTarget.querySelector('input').value;toast(`Thanks for subscribing, ${email}! (demo)`);e.currentTarget.reset()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeCart();closeCheckout()}});
renderProducts();renderCart();
// Hero banner slider
// TechWorld hero slider
(() => {
  const hero = document.querySelector(".hero-wrap");
  if (!hero) return;

  const slides = [...hero.querySelectorAll(".hero-slide")];
  const dots = [...hero.querySelectorAll(".hero-dots span")];
  const prev = hero.querySelector(".hero-prev");
  const next = hero.querySelector(".hero-next");

  if (slides.length < 2) {
    console.log("Hero slides not found. Check HTML structure.");
    return;
  }

  let current = 0;

  function showSlide(index) {
    current = (index + slides.length) % slides.length;

    slides.forEach((slide, i) => {
      slide.classList.toggle("active", i === current);
    });

    dots.forEach((dot, i) => {
      dot.classList.toggle("active", i === current);
    });
  }

  prev?.addEventListener("click", () => showSlide(current - 1));
  next?.addEventListener("click", () => showSlide(current + 1));

  dots.forEach((dot, i) => {
    dot.style.cursor = "pointer";
    dot.addEventListener("click", () => showSlide(i));
  });

  showSlide(0);
})();
// TechWorld hero arrows and dots
document.addEventListener("DOMContentLoaded", () => {
  const hero = document.querySelector(".hero-wrap");
  if (!hero) return;

  const prev = hero.querySelector(".hero-prev");
  const next = hero.querySelector(".hero-next");
  const dots = [...hero.querySelectorAll(".hero-dots span")];

  // Existing hero visual ko slide ki tarah switch karein
  const devices = [...hero.querySelectorAll(".hero-device")];
  let active = 0;

  function updateHero(index) {
    if (!devices.length) return;

    active = (index + devices.length) % devices.length;

    devices.forEach((device, i) => {
      device.style.opacity = i === active ? "1" : "0.25";
      device.style.transform = i === active
        ? "scale(1.05)"
        : "scale(0.95)";
    });

    dots.forEach((dot, i) => {
      dot.classList.toggle("active", i === active);
    });
  }

  prev?.addEventListener("click", () => updateHero(active - 1));
  next?.addEventListener("click", () => updateHero(active + 1));

  dots.forEach((dot, i) => {
    dot.style.cursor = "pointer";
    dot.addEventListener("click", () => updateHero(i));
  });
});
